class LmdbPreparedDomainStartupTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:prepared-domain:subject");
	private static final IRI OTHER = VF.createIRI("urn:prepared-domain:other");
	private static final IRI PREDICATE = VF.createIRI("urn:prepared-domain:predicate");
	private static final IRI RETAINED_OWNER = VF.createIRI("urn:prepared-domain:retained-owner");
	private static final Literal CANONICAL = VF.createLiteral("7", XSD.INT);
	private static final Literal NONCANONICAL = VF.createLiteral("007", XSD.INT);

	private enum Profile {
		CURRENT,
		DISABLED,
		EXCLUDED,
		REBUILD_OFF
	}

	private record Seed(long predicateId, long objectId, boolean retainedOwner) {
	}

	@ParameterizedTest
	@CsvSource({ "DISABLED, CURRENT, true, true", "CURRENT, DISABLED, false, false",
			"EXCLUDED, CURRENT, true, true", "CURRENT, EXCLUDED, true, false",
			"DISABLED, REBUILD_OFF, false, false" })
	void profileTransitionsPerformRequiredMaintenanceBeforeUsingPreparedAuthority(Profile before, Profile after,
			boolean maintenance, boolean readable, @TempDir Path directory) throws Exception {
		Seed seed = seed(directory, config(before), false, false);
		List<LmdbStartupDiagnostics.Operation> operations = new ArrayList<>();
		LmdbStore reopened = new LmdbStore(directory.toFile(), config(after));
		LmdbStartupDiagnostics.OBSERVER.set(operations::add);
		try {
			reopened.init();
			assertRowsAndIds(reopened, seed, 1L, false);
			TripleStore triples = reopened.getBackingStore().getTripleStore();
			assertEquals(readable, triples.getKnownRdfTermDomain(seed.predicateId()).isPresent());
			if (readable) {
				assertTrue(triples.getKnownRdfTermDomain(seed.predicateId())
						.orElseThrow()
						.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
			}
			triples.trustedTransactionId();
			if (maintenance) {
				assertTrue(operations.contains(LmdbStartupDiagnostics.Operation.DISCOVERY),
						"required domain writes must use complete ordinary startup before prepared authority is assumed");
			} else {
				assertEquals(List.of(), operations, "a profile requiring no native writes must retain bounded startup");
			}
		} finally {
			LmdbStartupDiagnostics.OBSERVER.remove();
			reopened.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void unrequestedDegradationCandidatesRetainExactPreparedTransactions(boolean autoRebuild,
			@TempDir Path directory) throws Exception {
		Seed seed = seed(directory, config(Profile.CURRENT), true, false);
		LmdbStoreConfig next = config(Profile.CURRENT).setPredicateGuaranteeIndexAutoRebuild(autoRebuild);
		assertPreparedReopen(directory, next, seed, 2L, true);
	}

	@Test
	void disabledAutomaticRebuildRetainsPreparedAuthorityForMarkedPredicates(@TempDir Path directory)
			throws Exception {
		Seed seed = seed(directory, config(Profile.CURRENT), true, true);
		assertPreparedReopen(directory, config(Profile.REBUILD_OFF), seed, 2L, false);
		LmdbStore resumed = new LmdbStore(directory.toFile(), config(Profile.CURRENT));
		try {
			resumed.init();
			assertRowsAndIds(resumed, seed, 2L, false);
			assertTrue(resumed.getBackingStore()
					.getTripleStore()
					.getKnownRdfTermDomain(seed.predicateId())
					.orElseThrow()
					.has(RdfTermDomain.Fact.CANONICAL_INTEGER),
					"turning automatic rebuild back on must still honor the deferred marker");
		} finally {
			resumed.shutDown();
		}
	}

	private static void assertPreparedReopen(Path directory, LmdbStoreConfig config, Seed seed, long count,
			boolean hasNoncanonical) throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		PreparedBulkStore.Snapshot before = PreparedBulkStore.read(directory, properties, config);
		assertNotNull(before, "clean state without requested native maintenance must remain admissible");
		List<LmdbStartupDiagnostics.Operation> operations = new ArrayList<>();
		LmdbStore reopened = new LmdbStore(directory.toFile(), config);
		LmdbStartupDiagnostics.OBSERVER.set(operations::add);
		try {
			reopened.init();
			assertEquals(List.of(), operations);
			assertRowsAndIds(reopened, seed, count, hasNoncanonical);
			ValueStore values = (ValueStore) reopened.getBackingStore().getValueFactory();
			TripleStore triples = reopened.getBackingStore().getTripleStore();
			long activeValueTransactionId = values.lastTransactionId();
			assertTrue(activeValueTransactionId > before.values().transactionId(),
					"the active dictionary must advance the closed CLEAN generation during startup");
			assertEquals(values.trustedClosedTransactionId(), activeValueTransactionId,
					"the active dictionary generation must equal its last owned native transaction");
			assertEquals(before.triples().transactionId(), triples.trustedTransactionId());
			assertEquals(0L, reopened.getMapGrowthCount(),
					"prepared opening must finish without native map growth");
			RdfTermDomain known = triples.getKnownRdfTermDomain(seed.predicateId()).orElseThrow();
			assertFalse(known.has(RdfTermDomain.Fact.CANONICAL_INTEGER));
			assertEquals(known, triples.getPersistedRdfTermDomain(seed.predicateId()).orElseThrow());
		} finally {
			LmdbStartupDiagnostics.OBSERVER.remove();
			reopened.shutDown();
		}
	}

	private static Seed seed(Path directory, LmdbStoreConfig config, boolean weaken, boolean remove)
			throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(SUBJECT, PREDICATE, CANONICAL);
				connection.setNamespace("prepared", "urn:prepared-domain:namespace:");
				connection.commit();
				if (weaken) {
					connection.begin(IsolationLevels.SNAPSHOT);
					connection.addStatement(OTHER, PREDICATE, NONCANONICAL);
					if (remove) {
						// Keep every dictionary term live: this case isolates domain work from value reclamation.
						connection.addStatement(OTHER, RETAINED_OWNER, NONCANONICAL);
					}
					connection.commit();
				}
				if (remove) {
					connection.begin(IsolationLevels.SNAPSHOT);
					connection.removeStatements(OTHER, PREDICATE, NONCANONICAL);
					connection.commit();
				}
			}
			ValueStore values = (ValueStore) store.getBackingStore().getValueFactory();
			return new Seed(values.getId(PREDICATE), values.getId(CANONICAL), remove);
		} finally {
			store.shutDown();
		}
	}

	private static void assertRowsAndIds(LmdbStore store, Seed seed, long count, boolean hasNoncanonical)
			throws Exception {
		ValueStore values = (ValueStore) store.getBackingStore().getValueFactory();
		assertEquals(seed.predicateId(), values.getId(PREDICATE));
		assertEquals(seed.objectId(), values.getId(CANONICAL));
		try (SailConnection connection = store.getConnection()) {
			assertEquals(count, connection.size());
			assertTrue(connection.hasStatement(SUBJECT, PREDICATE, CANONICAL, false));
			assertEquals(hasNoncanonical, connection.hasStatement(OTHER, PREDICATE, NONCANONICAL, false));
			assertEquals(seed.retainedOwner(), connection.hasStatement(OTHER, RETAINED_OWNER, NONCANONICAL, false));
			assertEquals("urn:prepared-domain:namespace:", connection.getNamespace("prepared"));
		}
	}

	private static LmdbStoreConfig config(Profile profile) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true);
		switch (profile) {
		case DISABLED -> config.setPredicateGuaranteeIndexEnabled(false);
		case EXCLUDED -> config.setPredicateGuaranteeExcludedPredicates(PREDICATE.stringValue());
		case REBUILD_OFF -> config.setPredicateGuaranteeIndexAutoRebuild(false);
		case CURRENT -> {
		}
		}
		return config;
	}
}
